SELECT FROM ( WITH book AS ( WITH book1 AS ( SELECT '1' seq , ast09_book.* FROM ast09_book WHERE ast09_company_id = #{companyId} AND (ast09_ast_class_tree_id, ast09_keep_account_id, ast09_hold_date) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(ast09_hold_date) FROM ast09_book WHERE ast09_company_id = #{companyId} AND ast09_hold_date <= #{holdDate}
AND ast09_ast_class_tree_id = #{astClassTreeId}
AND ast09_keep_account_id = #{keepAccountId}
GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) UNION ALL SELECT '2' seq , ast11_book_id , ast11_hold_date , ast11_ast_class_tree_id , ast11_keep_account_id , ast11_hold_qty , ast11_pur_amt , ast11_book_amt , ast11_eval_amt , ast11_eval_pl , ast11_first_pur_amt , ast11_first_pur_date , ast11_company_id , ast11_for_pur_amt , ast11_for_book_amt , ast11_for_eval_amt , ast11_for_eval_pl , ast11_fx_pl , ast11_book_end_yn , ast11_acr_int_amt , ast11_for_acr_int_amt , ast11_oci , ast11_for_oci , ast11_lock_up_period_cd , ast11_lock_up_date , ast11_lock_up_qty FROM ast11_book_close WHERE ast11_company_id = #{companyId} AND (ast11_ast_class_tree_id, ast11_keep_account_id, ast11_hold_date) IN ( SELECT ast11_ast_class_tree_id, ast11_keep_account_id, MAX(ast11_hold_date) FROM ast11_book_close WHERE ast11_company_id = #{companyId} AND ast11_hold_date < #{holdDate}
AND ast11_ast_class_tree_id = #{astClassTreeId}
AND ast11_keep_account_id = #{keepAccountId}
GROUP BY ast11_ast_class_tree_id, ast11_keep_account_id ) ) SELECT * FROM book1 WHERE (ast09_ast_class_tree_id, ast09_keep_account_id, to_char(ast09_hold_date,'yyyymmdd')||seq) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(to_char(ast09_hold_date,'yyyymmdd')||seq) FROM book1 GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) ) SELECT COALESCE(ast06_tr_id, f_create_seq()) as ast06_tr_id , COALESCE(ast06_ast_class_tree_id, ast09_ast_class_tree_id) as ast06_ast_class_tree_id , COALESCE(ast06_date , #{holdDate}) as ast06_date , COALESCE(ast06_tr_cd, CASE WHEN COALESCE(ast1.ast01_eval_type,'1') = '2' THEN '3610' ELSE '3600' END) as ast06_tr_cd , ( SELECT ast05_tr_nm FROM ast05_tr_code WHERE ast05_company_id = ast09_company_id AND ast05_tr_cd = COALESCE(ast06_tr_cd, CASE WHEN COALESCE(ast1.ast01_eval_type,'1') = '2' THEN '3610' ELSE '3600' END) ) as ast06_tr_nm , CASE WHEN ast1.ast01_eval_type = '2' THEN COALESCE(ast06_amt, 0) WHEN ast1.ast01_eval_type = '3' THEN COALESCE(ast06_amt, f_nvl(ast09_eval_amt, ast09_book_amt)) ELSE COALESCE( ast06_amt , trunc( ast09_hold_qty * trunc(f_get_price(#{holdDate}, ast09_ast_class_tree_id),2) / COALESCE(ast1.ast01_tr_unit,1) ) ) END as ast06_amt , ast06_note as ast06_note , ast06_person_id as ast06_person_id , f_emp_kor_nm(ast06_person_id) as ast06_person_nm , COALESCE(ast06_company_id, ast09_company_id) as ast06_company_id , sys15_corp_id as ast06_corp_id , sys15_corp_nm as ast06_corp_nm , sys15_corp_nm||'('||f_ast_class_tree_nm(ast09_keep_account_id)||')' as ast06_corp_account_nm , COALESCE(ast06_cur_cd, ast1.ast01_cur_cd) as ast06_cur_cd , CASE WHEN ast1.ast01_eval_type = '2' THEN COALESCE(ast06_for_amt, 0) WHEN ast1.ast01_eval_type = '3' THEN COALESCE(ast06_for_amt, f_nvl(ast09_for_eval_amt, ast09_for_book_amt)) ELSE COALESCE(ast06_for_amt, ast09_for_eval_amt) END as ast06_for_amt , ast06_fx_rate as ast06_fx_rate , CASE WHEN ast06_tr_id IS NOT NULL THEN '평가' ELSE '' END as ast06_eval_yn_nm , CASE WHEN ast09_lock_up_date IS NOT NULL THEN f_get_datediff(f_get_biz_date2(0, ast09_lock_up_date, '+1', 'true'), #{holdDate}, '2') ELSE f_get_datediff(ast09_first_pur_date, #{holdDate}, '2') END as ast06_hold_period , f_get_account_close_date(ast09_company_id, #{holdDate}, -1) as ast06_pre_close_date , COALESCE(( SELECT MAX(ast06_date) FROM ast06_tr INNER JOIN ast08_tr_finance ON ast08_tr_id = ast06_tr_id WHERE ast06_company_id = ast09_company_id AND ast06_ast_class_tree_id = ast09_ast_class_tree_id AND ast08_account_id = ast09_keep_account_id AND ast06_date < #{holdDate} AND ast06_tr_cd IN ('3600','3610') /* (3600:금융상품 평가/3610:금융상품 이자평가) */ ), ast09_first_pur_date) as ast06_pre_eval_date , COALESCE(ast1.ast01_eval_type,'1') as ast06_eval_type , f_cdnm('AssetEvalType', COALESCE(ast1.ast01_eval_type,'1'), ast09_company_id, ast09_hold_date) as ast06_eval_type_nm , act02_journal_id as ast06_journal_id , f_ast_class_tree_nm(ast09_ast_class_tree_id) as ast06_class_tree_nm , f_ast_class_tree_nm_allpath(ast09_ast_class_tree_id) as ast06_class_tree_full_nm , ast08_tr_finance_id as ast08_tr_finance_id , ast09_keep_account_id as ast08_account_id , ast09_hold_qty as ast08_qty , CASE WHEN ast06_tr_id IS NOT NULL THEN ast08_price ELSE trunc(f_get_price(#{holdDate}, ast09_ast_class_tree_id),2) END as ast08_price , ast09_book_amt as ast08_book_amt , ast09_for_book_amt as ast08_for_book_amt , ast08_pl as ast08_pl , COALESCE(ast1.ast01_tr_unit,1) as ast08_tr_unit , f_cdnm('ItemMClassCode',ast1.ast01_item_m_class_cd,ast09_company_id,ast09_hold_date) ||CASE WHEN substr(ast1.ast01_item_s_class_cd,5) = '99' THEN '' ELSE '('||f_cdnm('ItemSClassCode',ast1.ast01_item_s_class_cd,ast09_company_id,ast09_hold_date)||')' END as ast08_ast_class_nm , ast2.ast01_seq as account_seq , ast1.ast01_seq as ast_seq FROM book INNER JOIN ast01_class_tree ast1 ON ast1.ast01_class_tree_id = ast09_ast_class_tree_id INNER JOIN ast01_class_tree ast2 ON ast2.ast01_class_tree_id = ast09_keep_account_id INNER JOIN sys15_corp ON sys15_corp_id = ast2.ast01_corp_id LEFT OUTER JOIN ( SELECT * FROM ast06_tr INNER JOIN ast08_tr_finance ON ast08_tr_id = ast06_tr_id LEFT OUTER JOIN act02_journal ON act02_tr_id = ast06_tr_id WHERE ast06_company_id = #{companyId} AND ast06_date = #{holdDate} AND ast06_tr_cd IN ('3600','3610') /* (3600:금융상품 평가/3610:금융상품 이자평가) */ ) tr ON ( ast06_company_id = ast09_company_id AND ast06_ast_class_tree_id = ast09_ast_class_tree_id AND ast08_account_id = ast09_keep_account_id AND ast06_date = #{holdDate} ) WHERE COALESCE(ast1.ast01_asset_type,'1') like #{assetType} AND ( ast1.ast01_item_l_class_cd = '20' OR ( ast1.ast01_eval_type = '2' AND #{holdDate} BETWEEN ast1.ast01_issue_date AND COALESCE(ast1.ast01_mat_date,'2999-12-31'::date ) ) ) AND COALESCE(ast09_book_end_yn,'false') != 'true'
AND ( ( '1' = #{abroType} AND /* 1:국내 */ COALESCE(ast1.ast01_cur_cd,'KRW') = 'KRW' AND COALESCE(ast2.ast01_cur_cd,'KRW') = 'KRW' ) OR ( '2' = #{abroType} AND /* 2:국외 */ ( COALESCE(ast1.ast01_cur_cd,'KRW') != 'KRW' OR COALESCE(ast2.ast01_cur_cd,'KRW') != 'KRW' ) ) )
AND sys15_corp_id = #{corpId}
AND ( ( #{evalType} = '1' AND COALESCE(ast1.ast01_eval_type,'1') != '2' ) OR ( #{evalType} = '2' AND COALESCE(ast1.ast01_eval_type,'1') = '2' ) )
AND UPPER(CONCAT(sys15_corp_nm ,f_ast_class_tree_nm(ast09_keep_account_id) ,f_cdnm('ItemMClassCode',ast1.ast01_item_m_class_cd,ast09_company_id,ast09_hold_date) ,f_cdnm('ItemSClassCode',ast1.ast01_item_s_class_cd,ast09_company_id,ast09_hold_date) ,f_ast_class_tree_nm(ast09_ast_class_tree_id) ,ast06_note)) LIKE UPPER(#{searchText}) ) t ORDER BY ast06_corp_nm collate "ko_KR.utf8" asc , account_seq , ast08_ast_class_nm collate "ko_KR.utf8" asc , ast06_class_tree_nm collate "ko_KR.utf8" asc

mapper.update:
UPDATE ast06_tr
   SET ast06_ast_class_tree_id = #{r.astClassTreeId}
     , ast06_date              = #{r.date}
     , ast06_tr_cd             = #{r.trCode}
     , ast06_amt               = #{amt}
     , ast06_note              = #{r.note}
     , ast06_person_id         = #{personId}
     , ast06_cur_cd            = #{r.curCode}
     , ast06_for_amt           = #{forAmt}
     , ast06_fx_rate           = #{fxRate}
 WHERE ast06_tr_id      = #{r.trId}
   AND ast06_company_id = #{companyId}

UPDATE ast08_tr_finance
   SET ast08_book_amt     = #{r.bookAmt}
     , ast08_price        = #{price}
     , ast08_tr_amt       = #{trAmt}
     , ast08_pl           = #{pl}
     , ast08_for_tr_amt   = #{forTrAmt}
     , ast08_for_book_amt = #{r.forBookAmt}
     , ast08_for_pl       = #{forPl}
 WHERE ast08_tr_finance_id = #{financeId}

