DELETE FROM act02_journal
 WHERE act02_tr_id IN (
         SELECT ast06_tr_id
           FROM ast06_tr
                INNER JOIN ast08_tr_finance ON ast08_tr_id = ast06_tr_id
          WHERE ast06_company_id        = #{companyId}
            AND ast06_ast_class_tree_id = #{astClassTreeId}
            AND ast08_account_id        = #{keepAccountId}
            AND ast06_date              = CAST(#{date} AS date) + 1
            AND ast06_tr_cd             IN ('3601','3611') )

