INSERT INTO ast11_book_close
WITH book AS ( WITH book1 AS ( SELECT '1' seq , ast09_book.* FROM ast09_book WHERE ast09_company_id = #{companyId} AND (ast09_ast_class_tree_id, ast09_keep_account_id, ast09_hold_date) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(ast09_hold_date) FROM ast09_book WHERE ast09_company_id = #{companyId} AND ast09_hold_date <= #{holdDate}
AND ast09_ast_class_tree_id = #{astClassTreeId}
AND ast09_keep_account_id = #{keepAccountId}
GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) UNION ALL SELECT '2' seq , ast11_book_id , ast11_hold_date , ast11_ast_class_tree_id , ast11_keep_account_id , ast11_hold_qty , ast11_pur_amt , ast11_book_amt , ast11_eval_amt , ast11_eval_pl , ast11_first_pur_amt , ast11_first_pur_date , ast11_company_id , ast11_for_pur_amt , ast11_for_book_amt , ast11_for_eval_amt , ast11_for_eval_pl , ast11_fx_pl , ast11_book_end_yn , ast11_acr_int_amt , ast11_for_acr_int_amt , ast11_oci , ast11_for_oci , ast11_lock_up_period_cd , ast11_lock_up_date , ast11_lock_up_qty FROM ast11_book_close WHERE ast11_company_id = #{companyId} AND (ast11_ast_class_tree_id, ast11_keep_account_id, ast11_hold_date) IN ( SELECT ast11_ast_class_tree_id, ast11_keep_account_id, MAX(ast11_hold_date) FROM ast11_book_close WHERE ast11_company_id = #{companyId} AND ast11_hold_date < #{holdDate}
AND ast11_ast_class_tree_id = #{astClassTreeId}
AND ast11_keep_account_id = #{keepAccountId}
GROUP BY ast11_ast_class_tree_id, ast11_keep_account_id ) ) SELECT * FROM book1 WHERE (ast09_ast_class_tree_id, ast09_keep_account_id, to_char(ast09_hold_date,'yyyymmdd')||seq) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(to_char(ast09_hold_date,'yyyymmdd')||seq) FROM book1 GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) )
SELECT f_create_seq() , ast09_book_id , #{holdDate} , ast09_ast_class_tree_id , ast09_keep_account_id , ast09_hold_qty , ast09_pur_amt , CASE WHEN (f_get_account_close_date(ast09_company_id, #{holdDate}, 0) = #{holdDate} OR f_get_account_close_date(ast09_company_id, #{holdDate}, -1) = ast09_hold_date ) THEN (CASE WHEN ast01_eval_type = '2' THEN ast09_book_amt ELSE ast09_eval_amt END) ELSE ast09_book_amt END /*(ast11_book_amt)*/ , COALESCE(ast09_eval_amt,0) /*(ast11_eval_amt)*/ , CASE WHEN (f_get_account_close_date(ast09_company_id, #{holdDate}, 0) = #{holdDate} OR f_get_account_close_date(ast09_company_id, #{holdDate}, -1) = ast09_hold_date ) THEN 0 ELSE COALESCE(ast09_eval_pl,0) END /*(ast11_eval_pl)*/ , ast09_first_pur_amt , ast09_first_pur_date , ast09_company_id , ast09_for_pur_amt , CASE WHEN (f_get_account_close_date(ast09_company_id, #{holdDate}, 0) = #{holdDate} OR f_get_account_close_date(ast09_company_id, #{holdDate}, -1) = ast09_hold_date ) THEN (CASE WHEN ast01_eval_type = '2' THEN ast09_for_book_amt ELSE ast09_for_eval_amt END) ELSE ast09_for_book_amt END /*(ast11_for_book_amt)*/ , COALESCE(ast09_for_eval_amt,0) /*(ast11_for_eval_amt)*/ , CASE WHEN (f_get_account_close_date(ast09_company_id, #{holdDate}, 0) = #{holdDate} OR f_get_account_close_date(ast09_company_id, #{holdDate}, -1) = ast09_hold_date ) THEN 0 ELSE COALESCE(ast09_for_eval_pl,0) END /*(ast11_for_eval_pl)*/ , CASE WHEN (f_get_account_close_date(ast09_company_id, #{holdDate}, 0) = #{holdDate} OR f_get_account_close_date(ast09_company_id, #{holdDate}, -1) = ast09_hold_date ) THEN 0 ELSE COALESCE(ast09_fx_pl,0) END /*(ast11_fx_pl)*/ , ast09_book_end_yn , ast09_acr_int_amt , ast09_for_acr_int_amt , CASE WHEN COALESCE(ast01_account_type,'99') IN ('20','41','42') -- 회계구분이 '20:기타포괄손익(OCI)/41:지분법-연결/42:지분법-비연결'인 경우 THEN COALESCE(ast09_oci,0) + (CASE WHEN (f_get_account_close_date(ast09_company_id, #{holdDate}, 0) = #{holdDate} OR f_get_account_close_date(ast09_company_id, #{holdDate}, -1) = ast09_hold_date ) THEN COALESCE(ast09_eval_pl,0) ELSE 0 END) ELSE 0 END /*(ast11_oci)*/ , CASE WHEN COALESCE(ast01_account_type,'99') IN ('20','41','42') -- 회계구분이 '20:기타포괄손익(OCI)/41:지분법-연결/42:지분법-비연결'인 경우 THEN COALESCE(ast09_for_oci,0) + (CASE WHEN (f_get_account_close_date(ast09_company_id, #{holdDate}, 0) = #{holdDate} OR f_get_account_close_date(ast09_company_id, #{holdDate}, -1) = ast09_hold_date ) THEN COALESCE(ast09_for_eval_pl,0) ELSE 0 END) ELSE 0 END /*(ast11_for_oci)*/ , ast09_lock_up_period_cd , ast09_lock_up_date , ast09_lock_up_qty FROM book INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast09_ast_class_tree_id WHERE COALESCE(ast09_book_end_yn,'false') != 'true'

