mapper.insert:
INSERT INTO sys99_print
       ( sys99_print_id, sys99_company_id, sys99_person_id, sys99_window_class_nm, sys99_group_id
       , sys99_string06, sys99_date01, sys99_string01, sys99_string02, sys99_string03
       , sys99_double01, sys99_long01, sys99_double02, sys99_long02, sys99_long03
       , sys99_string04, sys99_string05 )
VALUES ( #{printId}, #{companyId}, #{personId}, #{windowClassName}, #{groupId}
       , #{r.evalYnName}, #{r.date}, #{r.corpAccountName}, #{r.astClassName}, #{r.classTreeName}
       , #{r.qty}, #{r.financeBookAmt}, #{r.price}, #{r.amt}, #{pl}
       , #{r.note}, #{r.personName} )
